INSERT INTO `content_aboutpagecontent` (`id`, `created_at`, `updated_at`, `title`, `intro`, `body`, `image`) VALUES (1,'2026-09-14 16:29:44.325000','2026-09-26 19:49:22.166790','درباره اوستا سرویس','اوستا سرویس یک کسب‌وکار خدمات فنی در حوزه تعمیر پکیج ، کولر گازی ، تصفیه آب ، یخچال ، لباسشویی و ظرفشویی در استان تهران است که با سابقه ایی بیش از 40 سال در حوزه فنی و تعمیرات دارد','ما روی سرویس و تعمیر تمرکز کردیم این تمرکز باعث می‌شود تجربه کار با انواع برندها و مدل‌های رایج بازار ایران انباشته شود و تشخیص دقیق‌تر و سریع‌تری داشته باشیم.\r\n\r\nروال کار ما ساده است: شما درخواست را آنلاین ثبت می‌کنید، تعمیرکار تماس می‌گیرد، مشکل و برآورد هزینه اعلام می‌شود و پس از توافق، تعمیر در محل انجام می‌شود.\r\n\r\nبرای ما مهم است که قبل از شروع کار، وضعیت دستگاه و هزینه برایتان شفاف باشد.','');
/*!40000 ALTER TABLE `content_aboutpagecontent` ENABLE KEYS */;
UNLOCK TABLES;

