CREATE TABLE `content_brand` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  `seo_title` varchar(180) NOT NULL,
  `meta_description` longtext NOT NULL,
  `og_image` varchar(100) NOT NULL,
  `name` varchar(120) NOT NULL,
  `slug` varchar(140) NOT NULL,
  `short_description` longtext NOT NULL,
  `content` longtext NOT NULL,
  `image` varchar(100) NOT NULL,
  `active` tinyint(1) NOT NULL,
  `sort_order` int(10) unsigned NOT NULL CHECK (`sort_order` >= 0),
  `logo_theme` varchar(5) NOT NULL DEFAULT 'light',
  `service_id` bigint(20) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `slug` (`slug`),
  KEY `content_brand_created_at_eb640056` (`created_at`),
  KEY `content_brand_service_id_6c24a032_fk_content_service_id` (`service_id`),
  CONSTRAINT `content_brand_service_id_6c24a032_fk_content_service_id` FOREIGN KEY (`service_id`) REFERENCES `content_service` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
