INSERT INTO `content_brand` (`id`, `created_at`, `updated_at`, `seo_title`, `meta_description`, `og_image`, `name`, `slug`, `short_description`, `content`, `image`, `active`, `sort_order`, `logo_theme`, `service_id`) VALUES (1,'2026-09-14 16:29:41.138000','2026-09-14 16:29:41.138000','','','','بوتان','butane','تعمیر پکیج بوتان در تهران؛ عیب‌یابی ارورها، شیر سه‌Way و مدار فرمان.','پکیج‌های بوتان در ساختمان‌های تهران بسیار رایج هستند و در صورت سرویس نادرست ممکن است دچار ارور، خاموشی مکرر یا افت فشار آب گرم شوند. در تعمیر پکیج بوتان ابتدا مدل دستگاه و کد ارور بررسی می‌شود، سپس قطعات الکترونیکی، پمپ و مسیر آب گرم آزمایش می‌گردد.\n\nاگر پکیج بوتان شما روشن نمی‌شود، ارور می‌دهد یا آب گرم قطع‌ووصل دارد، درخواست تعمیر ثبت کنید تا هماهنگی لازم انجام شود.', 'brands/butane.png', 1, 1, 'light', 1),
(2,'2026-09-14 16:29:41.291000','2026-09-14 16:29:41.291000','','','','ایران رادیاتور','iran-radiator','تعمیر پکیج ایران رادیاتور در تهران؛ رفع ارور، سرویس شعله و تعویض قطعات اصلی.','پکیج ایران رادیاتور از مدل‌های پرتقاضای بازار است و بیشتر خرابی‌های آن به مدار فرمان، حسگر شعله و شیر گاز مربوط می‌شود. در تعمیر پکیج ایران رادیاتور، پس از مشخص شدن کد ارور، مسیر آب گرم و گرمایش جداگانه تست می‌شود.\n\nبرای مشکل روشن نشدن، ارور دادن یا نشتی آب، درخواست خود را ثبت کنید.', 'brands/iran-radiator.png', 1, 2, 'dark', 1),
(3,'2026-09-14 16:29:41.447000','2026-09-14 16:29:41.447000','','','','شاپه','chappee','تعمیر پکیج شاپه در تهران؛ رفع خاموشی، افت فشار و صدای غیرعادی.','پکیج‌های شاپه معمولاً بعد از سال‌ها کار دچار رسوب مبدل یا خرابی پمپ می‌شوند. در تعمیر پکیج شاپه، فشار مدار، عملکرد پمپ و مبدل اصلی بررسی و در صورت نیاز شست‌وشو یا تعویض قطعه انجام می‌شود.\n\nاگر پکیج شاپه شما خاموش می‌شود، صدا می‌دهد یا فشار آب گرم افت کرده، درخواست تعمیر ثبت کنید.', 'brands/chappee.svg', 1, 3, 'light', 1),
(4,'2026-09-14 16:29:41.591000','2026-09-14 16:29:41.591000','','','','آریستون','ariston','تعمیر پکیج آریستون در تهران؛ عیب‌یابی برد الکترونیکی و مدار آب گرم.','در پکیج‌های آریستون بخشی از خرابی‌ها به برد الکترونیکی و حسگرها برمی‌گردد و بخشی به رسوب مبدل. در تعمیر پکیج آریستون ابتدا کد ارور و ولتاژ قطعات بررسی و سپس مسیر آب گرم آزمایش می‌شود.\n\nبرای ارورهای مکرر، خاموشی یا عدم تولید آب گرم، درخواست خود را ثبت کنید.', 'brands/ariston.svg', 1, 4, 'light', 1),
(5,'2026-09-14 16:29:41.725000','2026-09-26 19:44:11.187595','','','','اوپتیما','optima','تعمیر پکیج اوپتیما در تهران؛ رفع مشکلات شعله، فشار و آب گرم.','پکیج اوپتیما در صورت افت فشار ساختمان یا رسوب، دچار خاموشی مکرر و نوسان دمای آب گرم می‌شود. در تعمیر پکیج اوپتیما، شیر پرکن، شیر امنیتی و مبدل کنترل و در صورت نیاز سرویس می‌شوند.\n\nاگر پکیج اوپتیما شما روشن نمی‌شود یا آب گرم ناپایدار است، درخواست تعمیر ثبت کنید.', 'brands/optima.png', 1, 5, 'light', 1),
(6,'2026-09-14 16:29:41.859000','2026-09-14 16:29:41.859000','','','','لورچ','lorch','تعمیر پکیج لورچ در تهران؛ رفع ارور، نشتی و مشکلات گرمایش.','پکیج‌های لورچ به دلیل ساخت قطعات حساس، در برابر رسوب و نوسان برق حساس‌اند. در تعمیر پکیج لورچ، مدار فرمان، حسگر دما و پمپ بررسی و قطعه معیوب شناسایی می‌شود.\n\nبرای ارور دادن، نشتی آب یا گرمای ناکافی رادیاتورها، درخواست خود را ثبت کنید.', 'brands/lorch.svg', 1, 6, 'light', 1),
(7,'2026-09-14 16:29:42.044000','2026-09-14 16:29:42.044000','','','','باکسی','baxi','تعمیر پکیج باکسی در تهران؛ عیب‌یابی کامل و رفع خاموشی مکرر.','در پکیج باکسی خاموشی مکرر معمولاً از کشیدن دود، حسگر شعله یا فشار مدار ناشی می‌شود. در تعمیر پکیج باکسی، تخلیه دود، فشار مدار و عملکرد شعله با ترتیب استاندارد بررسی می‌شود.\n\nاگر پکیج باکسی شما مدام خاموش می‌شود یا ارور می‌دهد، درخواست تعمیر ثبت کنید.', 'brands/baxi.svg', 1, 7, 'light', 1);
/*!40000 ALTER TABLE `content_brand` ENABLE KEYS */;
UNLOCK TABLES;

