INSERT INTO `content_faq` (`id`, `created_at`, `updated_at`, `question`, `answer`, `active`, `sort_order`) VALUES (1,'2026-09-14 16:29:43.337000','2026-09-26 13:28:48.928621','چطور درخواست تعمیر ثبت کنم؟','از دکمه «ثبت درخواست تعمیر» استفاده کنید و مراحل را طی کنید. پس از ثبت، کد پیگیری دریافت می‌کنید و تعمیرکار برای هماهنگی با شما تماس می‌گیرد.',1,2),
(2,'2026-09-14 16:29:43.526000','2026-09-14 16:29:43.526000','هزینه تعمیر چقدر است؟','هزینه عیب‌یابی {amount} تومان است؛ هزینه قطعه و کار اصلی بسته به مدل پکیج و قطعه معیوب متفاوت است و پیش از شروع کار در تماس تلفنی اعلام می‌شود تا با اطلاع کامل تأیید کنید.',1,2),
(3,'2026-09-14 16:29:43.721000','2026-09-26 19:59:41.696662','چه برندهایی را سرویس می‌کنید؟','تمامی دستگاه های موجود در بازار اعم از ایرانی و خارجی مانند دستگاه های مثله بوتان، ایران رادیاتور، شاپه، آریستون، لورچ ، باکسی ، نووا فلوریدا و دارنده نمایندگی رسمی اکثر برندها در ایران هستیم.',1,3),
(4,'2026-09-14 16:29:43.815000','2026-09-26 20:00:33.722786','در چه مناطقی خدمات ارائه می‌شود؟','خدمات در استان تهران ارائه می‌شود. هنگام ثبت درخواست، منطقه خود را وارد کنید تا هماهنگی انجام شود.',1,4),
(5,'2026-09-14 16:29:43.936000','2026-09-14 16:29:43.936000','آیا قبل از مراجعه هزینه اعلام می‌شود؟','بله؛ نوع خرابی و برآورد هزینه در تماس تلفنی اعلام می‌شود و پس از تأیید شما کار شروع می‌شود.',1,5),
(6,'2026-09-14 16:29:44.057000','2026-09-14 16:29:44.058000','اگر تصویر ارور پکیج را داشته باشم چه کنم؟','در مرحله آخر فرم درخواست می‌توانید تصویر پکیج یا پیغام خطا را بارگذاری کنید. این کار به تشخیص سریع‌تر کمک می‌کند.',1,6),
(7,'2026-09-21 11:47:56.212000','2026-09-26 19:54:31.490352','چرا اوستا سرویس؟','چون برای ما فقط انجام دادن یک کار مهم نیست؛ رضایت و اعتماد مشتری مهم‌تره.\r\n\r\nما سعی می‌کنیم کار رو با دقت، کیفیت و مسئولیت‌پذیری انجام بدیم و قبل از شروع، تا جای ممکن هزینه و روند کار رو شفاف توضیح بدیم. همچنین تلاش می‌کنیم زمان مشتری رو رعایت کنیم و کاری تحویل بدیم که از نتیجه‌اش خیالش راحت باشه.\r\n\r\nاوستا سرویس رو انتخاب کنید چون می‌خوایم یک مشتریِ راضی، فقط برای یک بار نباشه؛ بلکه با اعتماد دوباره برگرده و ما رو به دیگران معرفی کنه. برای ما اعتماد شما ارزشمنده و کیفیت کار، معرف ماست.',1,0),
(8,'2026-09-26 13:27:48.898141','2026-09-26 20:00:51.652014','ممد کیه؟','ممد دانشجوی مهندسی صنایع دانشگاه صنعتی امیرکبیر، علاقه‌مند به دنیای تکنولوژی، برنامه‌نویسی، هوش مصنوعی و کسب‌وکار است. او ذهنی کنجکاو و مسئله‌محور دارد و همیشه به دنبال یادگیری، تجربه‌کردن ایده‌های جدید و تبدیل مفاهیم به راه‌حل‌های واقعی است. ممد در کنار تحصیل دانشگاهی، در حوزه توسعه زیست‌بوم نوآوری و فناوری فعالیت می‌کند و به موضوعاتی مانند مدیریت محصول، توسعه کسب‌وکار، کارآفرینی و طراحی سیستم‌های نوآورانه علاقه‌مند است. او مسیر حرفه‌ای خود را با ترکیبی از تفکر تحلیلی، خلاقیت و یادگیری مستمر پیش می‌برد و باور دارد که ساختن، آزمودن و حتی اشتباه‌کردن، بخش جدایی‌ناپذیر رشد و پیشرفت است.',0,1);
/*!40000 ALTER TABLE `content_faq` ENABLE KEYS */;
UNLOCK TABLES;

