INSERT INTO `content_homepageitem` (`id`, `created_at`, `updated_at`, `kind`, `title`, `description`, `sort_order`, `home_id`) VALUES (1,'2026-09-25 12:12:51.304000','2026-09-25 12:12:51.304000','benefit','ثبت درخواست آسان','چند دقیقه وقت بگذارید و درخواست خود را آنلاین ثبت کنید؛ بدون نیاز به تماس‌های پیگیری.',1,1),
(2,'2026-09-25 12:12:51.339000','2026-09-25 12:12:51.340000','benefit','تماس سریع تعمیرکار','پس از ثبت درخواست، تعمیرکار برای هماهنگی با شما تماس می‌گیرد.',2,1),
(3,'2026-09-25 12:12:51.340000','2026-09-25 12:12:51.340000','benefit','عیب‌یابی شفاف','مشکل و برآورد هزینه قبل از شروع کار اعلام می‌شود.',3,1),
(4,'2026-09-25 12:12:51.341000','2026-09-25 12:12:51.341000','benefit','سرویس انواع برند','از بوتان و ایران رادیاتور تا آریستون و باکسی.',4,1),
(5,'2026-09-25 12:12:51.341000','2026-09-25 12:12:51.341000','step','ثبت درخواست','فرم چندمرحله‌ای را کامل کنید و تصویر ارور را (اختیاری) بارگذاری کنید.',1,1),
(6,'2026-09-25 12:12:51.341000','2026-09-25 12:12:51.341000','step','بررسی درخواست','جزئیات و منطقه مراجعه بررسی می‌شود.',2,1),
(7,'2026-09-25 12:12:51.341000','2026-09-25 12:12:51.342000','step','تماس تعمیرکار','برای هماهنگی زمان مراجعه و اعلام برآورد اولیه تماس گرفته می‌شود.',3,1),
(8,'2026-09-25 12:12:51.342000','2026-09-25 12:12:51.342000','step','انجام تعمیر','تعمیر در محل انجام و پس از تست نهایی تحویل داده می‌شود.',4,1);
