INSERT INTO `content_service` (`id`, `created_at`, `updated_at`, `seo_title`, `meta_description`, `og_image`, `name`, `slug`, `short_description`, `content`, `icon`, `image`, `active`, `sort_order`) VALUES (1,'2026-09-14 16:29:31.313000','2026-09-25 17:44:18.419000','تعمیر پکیج دیواری در تهران | عیب‌یابی و رفع ارور در محل','تعمیر پکیج دیواری در تهران و حومه؛ رفع ارور، افت فشار، نشتی و آب گرم قطع‌ووصل همه برندها در محل. ثبت درخواست آنلاین، تماس سریع تعمیرکار.','','تعمیر پکیج','boiler-repair','عیب‌یابی و تعمیر تخصصی پکیج دیواری (بوتان، ایران رادیاتور، شاپه، آریستون و...) در محل، در استان تهران.','پکیج دیواری قلب گرمایش ساختمان است؛ وقتی درست کار نکند هم آب گرم و هم گرمای رادیاتورها مختل می‌شود. در خدمت تعمیر پکیج، ابتدا مدل دستگاه و علائم خرابی بررسی می‌شود، سپس با ابزار مناسب عیب‌یابی انجام و قطعه معیوب مشخص می‌گردد.\n\n## چه مشکلاتی را تعمیر می‌کنیم؟\nروشن نشدن پکیج، نمایش کد ارور، افت مکرر فشار آب، نشتی آب از بدنه، آب گرم نوسان‌دار یا قطع‌ووصل، صدای غیرعادی پمپ و فن، و خاموش شدن ناگهانی شعله از رایج‌ترین مشکلاتی هستند که روزانه در تهران و حومه رفع می‌کنیم.\n\n## روی چه برندهایی تخصص داریم؟\nبوتان، ایران رادیاتور، لورچ، شاپه، آریستون، اپتیما و باکسی — برای هر برند قطعات رایج و نقاط ضعف متداول را می‌شناسیم؛ لیست کامل در بخش برندها آمده است.\n\n## مراحل کار از ثبت درخواست تا تحویل\nدرخواست را آنلاین ثبت می‌کنید (با عکس ارور اگر دارید)، تعمیرکار برای هماهنگی تماس می‌گیرد، مشکل و برآورد هزینه قبل از شروع کار اعلام می‌شود و پس از تعمیر، دستگاه زیر بار تست و تحویل داده می‌شود.\n\n## سرویس دوره‌ای فراموش نشود\nبیشتر خرابی‌های بزرگ پکیج از بی‌سرویسی شروع می‌شود؛ رسوب مبدل و خفگی شعله با یک سرویس سالانه قابل پیشگیری است. اگر پکیج شما بیش از یک سال سرویس نشده، در همان درخواست سرویس دوره‌ای را هم یادداشت کنید.','wrench','',1,0),
(6,'2026-09-22 22:46:27.986000','2026-09-26 19:46:34.570395','','','','تصفیه آب','water-purifier','سرویس، تعویض فیلتر و تعمیر انواع تصفیه‌ آب خانگی در محل شما با قطعات مناسب دستگاه.','تصفیه آب برای ادامه تصفیه سالم به سرویس دوره‌ای نیاز دارد؛ فیلترهای رسوب‌گیر و کربنی معمولاً هر ۶ تا ۸ ماه و ممبران هر ۱تا ۲ سال باید تعویض شوند. در این خدمت وضعیت فیلترها، مخزن، شیر خروجی و شیر برقی بررسی و قطعات فرسوده با قطعات مناسب دستگاه تعویض می‌شود.\r\n\r\nافت فشار آب خروجی، تغییر طعم یا بوی آب، شن‌ریزی، نشتی از بدنه و روشن/خاموش شدن مکرر پمپ از رایج‌ترین مشکلاتی هستند که در این خدمت رفع می‌شوند. برای رزرو سرویس، درخواست خود را ثبت کنید یا با تعمیرکار تماس بگیرید.','droplets','',1,2);
/*!40000 ALTER TABLE `content_service` ENABLE KEYS */;
